import numpy as np
def bonds(f):
    L=open(f).read().split('\n'); n=int(L[0]); L=L[2:2+n]
    s=[l.split()[0] for l in L]; X=np.array([[float(x) for x in l.split()[1:]] for l in L])
    D=np.linalg.norm(X[:,None]-X[None],axis=2)
    r={'H':0.32,'C':0.75,'P':1.07,'Ir':1.4}
    return {(i,j) for i in range(n) for j in range(i+1,n) if D[i,j]<1.2*(r[s[i]]+r[s[j]]) and s[i]!='Ir' and s[j]!='Ir'}
a=bonds('init.xyz'); b=bonds('answer.xyz'); print('ligand bonds same:', a==b, len(a))
"; ls -l answer.xyz; head -3 answer.xyz
